class VendingMachine:
    INVENTORY_EMPTY_MESSAGE = "No items in inventory"

    def __init__(self):
        self._inventory = {}
        self._balance = 0

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, amount):
        if amount < 0:
            raise ValueError("Balance cannot be negative")
        self._balance = amount

    @property
    def inventory(self):
        return self._inventory

    @inventory.setter
    def inventory(self, inventory_dict):
        if inventory_dict is None:
            self._inventory = {}
        else:
            self._inventory = dict(inventory_dict)

    def get_item_info(self, item_name):
        return self._inventory.get(item_name)

    def set_item_quantity(self, item_name, quantity):
        if item_name in self._inventory:
            self._inventory[item_name]['quantity'] = max(0, quantity)

    def add_item(self, item_name, price, quantity):
        if not self._restock_existing_item(item_name, quantity):
            self._inventory[item_name] = {'price': price, 'quantity': quantity}

    def _restock_existing_item(self, item_name, quantity):
        if item_name in self._inventory:
            self._inventory[item_name]['quantity'] += quantity
            return True
        return False

    def insert_coin(self, amount):
        self._balance += amount
        return self._balance

    def purchase_item(self, item_name):
        item_info = self.get_item_info(item_name)
        if item_info is None:
            return False
        if self._can_purchase(item_info):
            self._balance -= item_info['price']
            self.set_item_quantity(item_name, item_info['quantity'] - 1)
            return self.balance
        return False

    def _can_purchase(self, item_info):
        return item_info['quantity'] > 0 and self._balance >= item_info['price']

    def restock_item(self, item_name, quantity):
        if not self._restock_existing_item(item_name, quantity):
            self.add_item(item_name, 0, quantity)
        return item_name in self._inventory

    def display_items(self):
        if not self._inventory:
            return self.INVENTORY_EMPTY_MESSAGE
        return self._format_inventory_display()

    def _format_inventory_display(self):
        item_lines = []
        for item_name, item_info in self._inventory.items():
            item_lines.append(f"{item_name} - ${item_info['price']} [{item_info['quantity']}]")
        return "\n".join(item_lines)
